import React from 'react';

export const DATAPATTERN_LOGO_DATA_URI =
  'data:image/png;base64,';

interface DataPatternLogoProps
  extends React.ImgHTMLAttributes<HTMLImageElement> {
  className?: string;
}

export const DataPatternLogo: React.FC<DataPatternLogoProps> = ({
  className = 'h-[42px] w-auto select-none object-contain',
  alt = 'DataPattern - Ensure Transformation',
  ...props
}) => {
  return (
    <img
      src={DATAPATTERN_LOGO_DATA_URI}
      alt={alt}
      className={className}
      {...props}
    />
  );
};

export default DataPatternLogo;
